// === Tab: mySketch ===
//p5.js shader basic structure ref from https://www.openprocessing.org/sketch/920144

let theShader
let balls = []
let ballCount = 200
let theta = 0

function preload(){
	theShader = createShader(vert, frag)
}

function setup() {
	createCanvas(windowWidth, windowHeight, WEBGL)
	noStroke()
	for(var i=0;i<ballCount;i++){
		let bRand = round(random());
		let bV = random(-2,2);
		balls.push({
			id: i,
			p: createVector(bRand, bRand),
			v: createVector(bV, bV)
		})
	}
	background(100);
}

function draw() {
	shader(theShader)
	theShader.setUniform('u_resolution',[windowWidth/1000,windowHeight/1000])
	theShader.setUniform('u_time',millis()/1000)
	theShader.setUniform('u_mouse',[floor((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX)))/width), floor((window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY)))/height)])
	let arr = balls.map(b=>([b.p.x,b.p.y]))
	let passData = []
	arr.forEach(a=>passData=passData.concat(a))
	theShader.setUniform('balls',passData)

	balls.forEach(ball=>{
		// let rr = sin(ball.id+frameCount/100,1)
		// let angle = 4*PI*noise(ball.id,frameCount/1000,100000)
		ball.p.x= noise(ball.id,frameCount/1000+sin((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX)))/width),1)*2-0.5
		ball.p.y= noise(ball.id,frameCount/1000+sin((window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY)))/height),100000)*2-0.5
		// ball.p.add(ball.v)
		ball.v.x+=(((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX)))*0.2)/width-ball.p.x)/100
		ball.v.y+=(((window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY)))*0.2)/height-ball.p.y)/100
		if(ball.v.x <= 0 || ball.v.x >= width){
      ball.v.x *= -1;
    } else {
			ball.v.x *= 1;
		}
    if(ball.v.y <= 0 || ball.v.y >= height){
      ball.v.y *= -1;
    } else {
			ball.v.y *= 1;
		}
	})
	rect(0,0,width,height)
	stroke(255)
	// balls.forEach(ball1=>{
	// 	balls.forEach(ball2=>{
	// 		if (ball1.p.dist(ball2.p)<0.5){
	// 			line(ball1.p.x,ball1.p.y,ball2.p.x,ball2.p.y)
	// 		}
	// 	})
	// })

	// ellipse((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))), 20, 20);
}

// === Tab: frag ===
//noprotect
const frag = `
	#ifdef GL_ES
	precision mediump float;
	#endif

	uniform vec2 u_resolution;
	uniform vec2 u_mouse;
	uniform float u_time;

	float PI = 3.14159265359;
	float TWO_PI = 6.28318530718;

	uniform vec2 balls[${ballCount}];
	int ballCount = ${ballCount};

	varying vec2 vTexCoord;

	float rand(vec2 c){
		return fract(sin(dot(c.xy ,vec2(12.9898,78.233))) * 43758.5453);
	}

	mat2 rotate2d(float _angle){
    return mat2(cos(_angle),-sin(_angle), 
								sin(_angle),cos(_angle));
	}

	//	Classic Perlin 3D Noise 
	//	by Stefan Gustavson
	//
	vec4 permute(vec4 x){return mod(((x*34.0)+1.0)*x, 289.0);}
	vec4 taylorInvSqrt(vec4 r){return 1.79284291400159 - 0.85373472095314 * r;}
	vec3 fade(vec3 t) {return t*t*t*(t*(t*6.0-15.0)+10.0);}

	float cnoise(vec3 P){
		vec3 Pi0 = floor(P); // Integer part for indexing
		vec3 Pi1 = Pi0 + vec3(1.0); // Integer part + 1
		Pi0 = mod(Pi0, 400.0);
		Pi1 = mod(Pi1, 400.0);
		vec3 Pf0 = fract(P); // Fractional part for interpolation
		vec3 Pf1 = Pf0 - vec3(1.0); // Fractional part - 1.0
		vec4 ix = vec4(Pi0.x, Pi1.x, Pi0.x, Pi1.x);
		vec4 iy = vec4(Pi0.yy, Pi1.yy);
		vec4 iz0 = Pi0.zzzz;
		vec4 iz1 = Pi1.zzzz;

		vec4 ixy = permute(permute(ix) + iy);
		vec4 ixy0 = permute(ixy + iz0);
		vec4 ixy1 = permute(ixy + iz1);

		vec4 gx0 = ixy0 / 7.0;
		vec4 gy0 = fract(floor(gx0) / 7.0) - 0.5;
		gx0 = fract(gx0);
		vec4 gz0 = vec4(0.5) - abs(gx0) - abs(gy0);
		vec4 sz0 = step(gz0, vec4(0.0));
		gx0 -= sz0 * (step(0.0, gx0) - 0.5);
		gy0 -= sz0 * (step(0.0, gy0) - 0.5);

		vec4 gx1 = ixy1 / 7.0;
		vec4 gy1 = fract(floor(gx1) / 7.0) - 0.5;
		gx1 = fract(gx1);
		vec4 gz1 = vec4(0.5) - abs(gx1) - abs(gy1);
		vec4 sz1 = step(gz1, vec4(0.0));
		gx1 -= sz1 * (step(0.0, gx1) - 0.5);
		gy1 -= sz1 * (step(0.0, gy1) - 0.5);

		vec3 g000 = vec3(gx0.x,gy0.x,gz0.x);
		vec3 g100 = vec3(gx0.y,gy0.y,gz0.y);
		vec3 g010 = vec3(gx0.z,gy0.z,gz0.z);
		vec3 g110 = vec3(gx0.w,gy0.w,gz0.w);
		vec3 g001 = vec3(gx1.x,gy1.x,gz1.x);
		vec3 g101 = vec3(gx1.y,gy1.y,gz1.y);
		vec3 g011 = vec3(gx1.z,gy1.z,gz1.z);
		vec3 g111 = vec3(gx1.w,gy1.w,gz1.w);

		vec4 norm0 = taylorInvSqrt(vec4(dot(g000, g000), dot(g010, g010), dot(g100, g100), dot(g110, g110)));
		g000 *= norm0.x;
		g010 *= norm0.y;
		g100 *= norm0.z;
		g110 *= norm0.w;
		vec4 norm1 = taylorInvSqrt(vec4(dot(g001, g001), dot(g011, g011), dot(g101, g101), dot(g111, g111)));
		g001 *= norm1.x;
		g011 *= norm1.y;
		g101 *= norm1.z;
		g111 *= norm1.w;

		float n000 = dot(g000, Pf0);
		float n100 = dot(g100, vec3(Pf1.x, Pf0.yz));
		float n010 = dot(g010, vec3(Pf0.x, Pf1.y, Pf0.z));
		float n110 = dot(g110, vec3(Pf1.xy, Pf0.z));
		float n001 = dot(g001, vec3(Pf0.xy, Pf1.z));
		float n101 = dot(g101, vec3(Pf1.x, Pf0.y, Pf1.z));
		float n011 = dot(g011, vec3(Pf0.x, Pf1.yz));
		float n111 = dot(g111, Pf1);

		vec3 fade_xyz = fade(Pf0);
		vec4 n_z = mix(vec4(n000, n100, n010, n110), vec4(n001, n101, n011, n111), fade_xyz.z);
		vec2 n_yz = mix(n_z.xy, n_z.zw, fade_xyz.y);
		float n_xyz = mix(n_yz.x, n_yz.y, fade_xyz.x); 
		return 5.1 * n_xyz;
	}


	void main(){
		vec2 st = vTexCoord.xy /u_resolution.xy;
		st = rotate2d(sin(u_time*0.05)*PI*0.05) * st;

		vec3 color = vec3(0.);
		// vec3 color = vec3(st.x,st.y,(sin(u_time)+1.)/2.);
		float s=0.;
		for(int i=0;i<${ballCount};i++){
			vec2 ball = balls[i];
			float d = distance(ball,st);
			color.r+= 0.00002/pow(d,1.5+sin(ball.x)/5.);
			color.g+= 0.000005/pow(d,1.+sin(ball.y)/5.)+color.r/float(ballCount);
			color.b+= 0.00002/pow(d,1.2+sin(ball.x)/5.)+color.g/float(ballCount);
			s+=1./(pow(d,2.2+color.r/5.)+0.0001);
		}
		// s/=float(ballCount);
		// color.r*=1.5;
		// color.g*=0.8;
		// color.b*=1.5;

		color.r = color.g = color.b += cos(s/500.+.5)*0.9;
		// color.g+=sin(s/500.+.5);
		// color.b+=sin(s/500.+.1);
		// color.r+=cos(s/2000.)/2.;
		// color.g+=cos(s/5000.)/2.;
		// color.b+=cos(s/2000.)/2.;
		color.r = color.g = color.b -=cnoise(vec3(st.x*500.,st.y*400.,u_time*5.))/10.;
		// color.g-=cnoise(vec3(st.x*200.,st.y*300.,u_time*1.2+0.5))/10.;
		// color.b-=cnoise(vec3(st.x*100.,st.y*250.,u_time*1.1+2.))/10.;
		gl_FragColor= vec4(color,1.0);
	}

`

// === Tab: vert ===
const vert = `
	attribute vec3 aPosition;
	attribute vec2 aTexCoord;

	varying vec2 vTexCoord;

	void main() {
		vTexCoord = aTexCoord;

		vec4 positionVec4 = vec4(aPosition, 1.0);
		positionVec4.xy = floor(positionVec4.xy * 2.0 - 1.0);

		gl_Position = positionVec4;
	}
`;

